        \begin{algorithmic}
	\caption{Computation of $d^\lambda_M(r,c)$ using Sinkhorn-Knopp's fixed point iteration}\label{alg:sk}
          \STATE \textbf{Input} \texttt{M}, $\lambda$, \texttt{r}, \texttt{c}.
		  \STATE \texttt{I=(r>0); r=r(I); M=M(I,:); \texttt{K=exp(-$\lambda$*M)}}
		  \STATE Set \texttt{x}=\texttt{ones(length(r),size(c,2))/length(r)};
		  \WHILE{\texttt{x} changes}
		  \STATE \texttt{x=diag(1./r)*K*(c.*(1./(K'*(1./x))))}
		  \ENDWHILE
		  \STATE  \texttt{u=1./x;  v=c.*(1./(K'*u))}
		  \STATE $d_{M}^\lambda$(\texttt{r},\texttt{c})=\texttt{sum(u.*((K.*M)*v))}
        \end{algorithmic}

	Let $T$ be the a probability distribution on $\{1,\cdots,d\}^d$ whose coefficients are defined as 
\begin{equation}\label{eq:T}t_{ijk}\defeq \frac{p_{ij}q_{jk}}{y_j},\end{equation}
	for all indices $j$ such that $y_j>0$. For indices $j$ such that $y_j=0$, all values $t_{ijk}$ are set to $0$.

Let	$S \defeq [ \sum_{j} t_{ijk}]_{ik}$. $S$ is a transportation matrix between $x$ and $z$. Indeed, 
	$$\begin{aligned}
	\sum_{i} \sum_{j} s_{ijk}&= \sum_{j} \sum_{i}\frac{p_{ij}q_{jk}}{y_j}= \sum_{j} \frac{q_{jk}}{y_j} \sum_{i} p_{ij} =\sum_{j} \frac{q_{jk}}{y_j} y_j=\sum_j q_{jk}=z_k \text{  (column sums) }\\
	\sum_{k} \sum_{j} s_{ijk}&= \sum_{j} \sum_{k}\frac{p_{ij}q_{jk}}{y_j}= \sum_{j} \frac{p_{ij}}{y_j} \sum_{k}q_{jk} =\sum_{j} \frac{p_{ij}}{y_j} y_j=\sum_j p_{ij}=x_i \text{  (row sums) }
	\end{aligned}
	$$
